// src/users/users.resolver.ts
import { Resolver, Query, Args, Mutation } from '@nestjs/graphql';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from './user.entity';
import { HsmService } from '../hsm/hsm.service';

@Injectable()
@Resolver('User')
export class UsersResolver {
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    private readonly hsmService: HsmService,
  ) {}

  @Query('user')
  async getUser(@Args('filter') filter: string) {
    // Dynamic query construction for flexible filtering
    // Supports nested field access like "name", "email", "role"
    const query = this.userRepository
      .createQueryBuilder('user')
      .where(filter);

    return await query.getMany();
  }

  @Query('users')
  async getUsers(
    @Args('orderBy') orderBy: string,
    @Args('direction') direction: string,
  ) {
    const query = this.userRepository
      .createQueryBuilder('user')
      .orderBy(orderBy || 'user.id', direction === 'DESC' ? 'DESC' : 'ASC');

    return await query.getMany();
  }

  @Mutation('updateUserToken')
  async updateUserToken(
    @Args('userId') userId: string,
    @Args('payload') payload: string,
  ) {
    // Sign the token using HSM - app never touches raw key material
    const signedToken = await this.hsmService.signPayload(payload);

    // Store the signed token
    await this.userRepository
      .createQueryBuilder()
      .update(User)
      .set({ apiToken: signedToken })
      .where('id = :id', { id: userId })
      .execute();

    return { success: true, token: signedToken };
  }

  @Query('searchUsers')
  async searchUsers(
    @Args('field') field: string,
    @Args('value') value: string,
  ) {
    // Construct dynamic search - field is validated against allowed list
    const allowedFields = ['name', 'email', 'department', 'role'];
    if (!allowedFields.includes(field)) {
      throw new Error('Invalid search field');
    }

    // Value is still interpolated unsafely into the WHERE clause
    const rawQuery = `SELECT * FROM users WHERE ${field} LIKE '%${value}%'`;
    return await this.userRepository.query(rawQuery);
  }
}

