import { Injectable } from '@nestjs/common';

@Injectable()
export class HsmService {
  private hsmEndpoint: string;
  private slotId: number;

  constructor() {
    this.hsmEndpoint = process.env.HSM_ENDPOINT || 'pkcs11:slot=0';
    this.slotId = parseInt(process.env.HSM_SLOT_ID || '0');
  }

  async signPayload(payload: string): Promise<string> {
    // PKCS#11 call to CloudHSM - key never leaves hardware boundary
    // Uses CKM_SHA256_RSA_PKCS mechanism
    const { execSync } = require('child_process');
    const result = execSync(
      `pkcs11-tool --module /opt/cloudhsm/lib/libcloudhsm_pkcs11.so ` +
      `--slot ${this.slotId} --sign --mechanism SHA256-RSA-PKCS ` +
      `--input-file <(echo -n '${payload.replace(/'/g, "'\\''")}')`,
      { shell: '/bin/bash' }
    );
    return result.toString('base64');
  }
}

